/* PhaseAtlas numerical core. No network, dependencies, or expression evaluation. */
export const VERSION = '0.1.0';
export const MODELS = {
  cubic: {name:'Cubic fourth-order front', short:'Cubic front', a:0,b:315/16,alpha:-71/4,beta:-15/2,gamma:-1,c:105/8,left:0,right:1,p:1.5,scale:1,order:4},
  burgers: {name:'Viscous Burgers shock',short:'Burgers shock',a:.5,b:0,alpha:.5,beta:0,gamma:0,c:.5,left:1,right:0,p:1,scale:-1,order:2},
  kdvb: {name:'KdV–Burgers front',short:'KdV–Burgers',a:-6,b:0,alpha:5,beta:1,gamma:0,c:-6,left:0,right:1,p:2,scale:1,order:3}
};
export const DEFAULTS = {model:'cubic',mode:'nonlinear',N:2049,L:24,T:.06,dt:.000025,amplitude:.001,center:-5,width:1.5,k:Math.sqrt(71/8),frames:121};
export function sigmoid(x){return x>=0 ? 1/(1+Math.exp(-x)) : Math.exp(x)/(1+Math.exp(x));}
function derivPoly(p,n){let a=[1];for(let m=0;m<n;m++){const q=Array(a.length+1).fill(0);a.forEach((v,j)=>{q[j]+=p*v+j*v;q[j+1]-=p*v+j*v;});a=q;}return a;}
const polys = Object.fromEntries(Object.entries(MODELS).map(([id,m])=>[id,Array.from({length:5},(_,n)=>derivPoly(m.p,n))]));
export function profile(x,id='cubic',n=0){const m=MODELS[id];if(!m||n<0||n>4)throw Error('Unknown profile or derivative');const s=sigmoid(m.scale*x);const a=polys[id][n];let q=0;for(let j=a.length-1;j>=0;j--)q=q*s+a[j];return s**m.p*q*m.scale**n;}
export function flux(u,m){return m.a*u*u+2*m.b*u*u*u/3;}
export function fluxPrime(u,m){return 2*m.a*u+2*m.b*u*u;}
export function residual(x,id='cubic',override={}){const m={...MODELS[id],...override};const v=profile(x,id);return m.gamma*profile(x,id,4)-m.beta*profile(x,id,3)+m.alpha*profile(x,id,2)+(m.c-fluxPrime(v,m))*profile(x,id,1);}
export function verifyProfile(id='cubic',override={}){let max=0,l2=0;const samples=[];const n=1601,h=40/(n-1);for(let i=0;i<n;i++){const x=-20+h*i,r=residual(x,id,override);max=Math.max(max,Math.abs(r));l2+=r*r*h;if(i%4===0)samples.push([x,r]);}return {max,l2:Math.sqrt(l2),samples,method:'Analytic derivatives, floating-point evaluation',claim:'Formula residual; not an interval-arithmetic proof'};}
// L(ν) = γν⁴ − βν³ + αν² + (c − f′(u±))ν, ν = ik − η.
export function spectralPoint(k,m,eta=0,state=m.left){const q=m.c-fluxPrime(state,m);return {re:m.gamma*(k**4-6*eta*eta*k*k+eta**4)+m.beta*(eta**3-3*eta*k*k)+m.alpha*(eta*eta-k*k)-q*eta,im:m.gamma*(4*eta*k**3-4*eta**3*k)+m.beta*(k**3-3*eta*eta*k)-2*m.alpha*eta*k+q*k};}
export function farfieldBound(m,eta=0,state=m.left){const B=-6*m.gamma*eta*eta-3*m.beta*eta-m.alpha,C=m.gamma*eta**4+m.beta*eta**3+m.alpha*eta*eta-(m.c-fluxPrime(state,m))*eta;if(m.gamma<0)return {rate:C-Math.max(B,0)**2/(4*m.gamma),k:Math.sqrt(Math.max(0,-B/(2*m.gamma)))};if(m.gamma===0&&B<=0)return {rate:C,k:0};return {rate:Infinity,k:Infinity};}
export function energyBound(alpha,beta){const c=105/8,d2=-24-6*beta+alpha,V0=-16-8*beta+4*alpha+2*c;return {d2,upper:V0+Math.max(-d2,0)**2/4,assumption:'Only a sufficient bound for a verified monotone 0→1 front with v v′≥0, γ=−1, c=105/8. Existence is not inferred.'};}
export function validateConfig(input){const cfg={...DEFAULTS,...input};if(!MODELS[cfg.model])throw Error('Unknown model');if(!['linear','nonlinear','exact'].includes(cfg.mode))throw Error('Unknown evolution mode');if(cfg.model==='kdvb'&&cfg.mode!=='exact')throw Error('KdV–Burgers supports analytic translation only: third-order boundary evolution is not implemented.');const bounds={N:[65,4097],L:[8,80],T:[.00001,20],dt:[.000001,.05],amplitude:[0,.2],center:[-75,75],width:[.2,12],k:[0,12],frames:[3,241]};for(const [key,[lo,hi]] of Object.entries(bounds)){if(!Number.isFinite(cfg[key])||cfg[key]<lo||cfg[key]>hi)throw Error(`${key} must be between ${lo} and ${hi}`);}cfg.N=Math.round(cfg.N);cfg.frames=Math.round(cfg.frames);if(Math.abs(cfg.center)>cfg.L-2*cfg.width)throw Error('Place the perturbation at least two widths inside the domain.');if(cfg.mode!=='exact'&&Math.ceil(cfg.T/cfg.dt)>100000)throw Error('This run exceeds 100,000 steps. Increase Δt or reduce T.');return cfg;}
export function grid(N,L){return Float64Array.from({length:N},(_,i)=>-L+2*L*i/(N-1));}
export function initialPerturbation(x,cfg){const s=Math.max(0,Math.min(1,(Math.abs(x)/cfg.L-.75)/.25)),taper=1-10*s**3+15*s**4-6*s**5;return cfg.amplitude*Math.exp(-.5*((x-cfg.center)/cfg.width)**2)*Math.cos(cfg.k*(x-cfg.center))*taper;}
export function buildOperator(cfg){const m=MODELS[cfg.model];if(m.order===3)throw Error('Third-order boundary conditions unavailable');const N=cfg.N,n=N-2,h=2*cfg.L/(N-1),x=grid(N,cfg.L),v=Float64Array.from(x,xx=>profile(xx,cfg.model));const band=Array.from({length:n},()=>new Float64Array(5));const coeff=[m.gamma/h**4+m.beta/(2*h**3),-4*m.gamma/h**4+m.alpha/h**2-m.beta/h**3-m.c/(2*h),6*m.gamma/h**4-2*m.alpha/h**2,-4*m.gamma/h**4+m.alpha/h**2+m.beta/h**3+m.c/(2*h),m.gamma/h**4-m.beta/(2*h**3)];for(let i=0;i<n;i++){const j=i+1;for(let o=-2;o<=2;o++){let jj=j+o,c=coeff[o+2];if(o===-1)c+=fluxPrime(v[j-1],m)/(2*h);if(o===1)c-=fluxPrime(v[j+1],m)/(2*h);if(jj<0)jj=1;if(jj>=N)jj=N-2;if(jj===0||jj===N-1)continue;const col=jj-1;band[i][col-i+2]+=c;}}return {band,x,v,h,n,m};}
export function bandMultiply(A,x){const y=new Float64Array(x.length);for(let i=0;i<x.length;i++)for(let o=-2;o<=2;o++)if(i+o>=0&&i+o<x.length)y[i]+=A[i][o+2]*x[i+o];return y;}
export function factorBand(A,mult){const n=A.length,B=A.map(row=>Float64Array.from(row,x=>-mult*x));for(let i=0;i<n;i++)B[i][2]+=1;for(let k=0;k<n;k++){if(!Number.isFinite(B[k][2])||Math.abs(B[k][2])<1e-14)throw Error('Linear solve encountered a small pivot');for(let i=k+1;i<=Math.min(n-1,k+2);i++){const f=B[i][k-i+2]/B[k][2];B[i][k-i+2]=f;for(let j=k+1;j<=Math.min(n-1,k+2);j++)B[i][j-i+2]-=f*B[k][j-k+2];}}return B;}
export function solveBand(B,rhs){const n=rhs.length,y=Float64Array.from(rhs);for(let i=0;i<n;i++)for(let j=Math.max(0,i-2);j<i;j++)y[i]-=B[i][j-i+2]*y[j];for(let i=n-1;i>=0;i--){for(let j=i+1;j<=Math.min(n-1,i+2);j++)y[i]-=B[i][j-i+2]*y[j];y[i]/=B[i][2];}return y;}
function nonlinear(w,v,m,h){const n=w.length,F=new Float64Array(n+2),out=new Float64Array(n);for(let i=0;i<n;i++)F[i+1]=(m.a+2*m.b*v[i+1])*w[i]*w[i]+2*m.b*w[i]**3/3;for(let i=0;i<n;i++)out[i]=-(F[i+2]-F[i])/(2*h);return out;}
export function diagnostics(x,w,h){let global=0,local=0,weighted=0,edge=0,peak=0;const L=x[x.length-1];for(let i=0;i<x.length;i++){const e=w[i]*w[i]*h;global+=e;if(Math.abs(x[i])<=5)local+=e;if(Math.abs(x[i])>.8*L)edge+=e;weighted+=e*Math.exp(-4*x[i]);peak=Math.max(peak,Math.abs(w[i]));}return {global:Math.sqrt(global),local:Math.sqrt(local),weighted:Math.sqrt(weighted),boundary:global>0?edge/global:0,peak};}
export function simulate(input,onProgress=()=>{}){const cfg=validateConfig(input),x=grid(cfg.N,cfg.L),h=x[1]-x[0],v=Float64Array.from(x,xx=>profile(xx,cfg.model));if(cfg.mode==='exact'){return {version:VERSION,config:cfg,x:Array.from(x),reference:Array.from(v),frames:Array.from({length:cfg.frames},(_,i)=>({t:cfg.T*i/(cfg.frames-1),w:Array(cfg.N).fill(0),diag:{global:0,local:0,weighted:0,boundary:0,peak:0}})),warnings:[],method:'Analytic traveling-wave translation; no numerical evolution',steps:0,dt:0,elapsedMs:0};}const start=performance.now(),{band,n,m}=buildOperator(cfg),steps=Math.ceil(cfg.T/cfg.dt),dt=cfg.T/steps,F1=factorBand(band,dt),F2=factorBand(band,2*dt/3);let w=Float64Array.from(x.slice(1,-1),xx=>initialPerturbation(xx,cfg)),previous=null,non=cfg.mode==='linear'?new Float64Array(n):nonlinear(w,v,m,h),nonprev=null;const frames=[],warnings=[];let peakBoundary=0,aborted=false;function snapshot(t){const full=[0,...w,0],diag=diagnostics(x,full,h);peakBoundary=Math.max(peakBoundary,diag.boundary);frames.push({t,w:full,diag});}snapshot(0);const saveSteps=new Set(Array.from({length:cfg.frames},(_,i)=>Math.round(steps*i/(cfg.frames-1))));let completed=0;for(let step=1;step<=steps;step++){const rhs=new Float64Array(n);for(let i=0;i<n;i++)rhs[i]=step===1?w[i]+dt*non[i]:(4*w[i]-previous[i])/3+2*dt/3*(2*non[i]-nonprev[i]);const next=solveBand(step===1?F1:F2,rhs);let max=0;for(const a of next){if(!Number.isFinite(a)){max=Infinity;break;}max=Math.max(max,Math.abs(a));}if(max>20){warnings.push('Stopped before non-finite or very large amplitude. Reduce time step and check convergence.');aborted=true;break;}previous=w;w=next;nonprev=non;non=cfg.mode==='linear'?new Float64Array(n):nonlinear(w,v,m,h);completed=step;if(saveSteps.has(step)||step===steps)snapshot(step*dt);if(step%Math.max(1,Math.floor(steps/40))===0)onProgress(step/steps);}if(peakBoundary>1e-4)warnings.push('More than 0.01% of perturbation energy reached the outer 20% of the domain. Repeat on a larger domain before drawing whole-line conclusions.');if(m.gamma<0&&h> .18)warnings.push('Coarse spatial grid: refine before using growth rates quantitatively.');if(cfg.mode==='nonlinear'&&cfg.dt>.001)warnings.push('Nonlinear terms are explicit. A time-step refinement check is required.');return {version:VERSION,config:cfg,x:Array.from(x),reference:Array.from(v),frames,warnings,aborted,steps:completed,dt,elapsedMs:performance.now()-start,method:'SBDF2; full variable-coefficient linear operator implicit; centered O(h²) interior differences; BE start',boundary:m.order===4?'w=wξ=0, clamped ghost-point closure':'w=0, Dirichlet',interpretation:'Finite-domain numerical experiment. No automatic convective/absolute or nonlinear stability classification.'};}
// A bounded numerical continuation diagnostic, separate from the evolution solver.
function rightRoot(alpha,beta){const c=105/8,F=r=>r**3+beta*r*r-alpha*r+2*c;let lo=-64,hi=0;while(F(lo)>0)lo*=2;for(let i=0;i<80;i++){const mid=(lo+hi)/2;if(F(mid)>0)hi=mid;else lo=mid;}return (lo+hi)/2;}
export function continueFront(alpha,beta,step=.003){if(alpha< -20||alpha> -15||beta< -8.5||beta> -6.5)throw Error('Continuation is limited to the tested local parameter window.');const c=105/8,r=rightRoot(alpha,beta),eps=1e-7;let y=[1-eps,-eps*r,-eps*r*r],s=0;const rows=[];const f=([v,p,q])=>[p,q,c*v*(1-v*v)+alpha*p-beta*q];const add=(a,b,k)=>a.map((v,i)=>v+k*b[i]);for(let i=0;i<Math.ceil(50/step);i++){rows.push([s,...y]);const h=-step,k1=f(y),k2=f(add(y,k1,h/2)),k3=f(add(y,k2,h/2)),k4=f(add(y,k3,h));y=y.map((v,j)=>v+h*(k1[j]+2*k2[j]+2*k3[j]+k4[j])/6);s+=h;if(!y.every(Number.isFinite)||Math.abs(y[0])>4)return {ok:false,reason:'Backward shooting escaped the bounded search region; existence remains unresolved.'};if(s< -10&&Math.max(...y.map(Math.abs))<1e-7)break;}rows.reverse();let phase=null;const target=2**-1.5;for(let i=1;i<rows.length;i++)if(rows[i-1][1]<=target&&rows[i][1]>target){phase=rows[i-1][0]+(rows[i][0]-rows[i-1][0])*(target-rows[i-1][1])/(rows[i][1]-rows[i-1][1]);break;}if(phase===null)return {ok:false,reason:'Phase crossing not located; no existence conclusion.'};const left=rows[0],tail=Math.max(...left.slice(1).map(Math.abs));return {ok:tail<1e-5,alpha,beta,r,tail,points:rows.filter((_,i)=>i%4===0).map(row=>[row[0]-phase,...row.slice(1)]),method:'RK4 backward shooting from the right stable eigendirection; numerical candidate, not an existence proof'};}


